data = sys.stdin.read()
line = data.split("\n")[0].rstrip("\r")
letters = digits = spaces = others = 0
for ch in line:
    if ("a" <= ch <= "z") or ("A" <= ch <= "Z"):
        letters += 1
    elif "0" <= ch <= "9":
        digits += 1
    elif ch == " ":
        spaces += 1
    else:
        others += 1
print(letters, digits, spaces, others)

