#include <stdio.h>
#include <ctype.h>

int main(void) {
    char s[1000];
    int letters = 0, digits = 0, spaces = 0, others = 0;
    if (fgets(s, sizeof s, stdin) == NULL) {
        printf("0 0 0 0\n");
        return 0;
    }
    for (int i = 0; s[i] != '\0'; i++) {
        unsigned char c = (unsigned char)s[i];
        if (c == '\n' || c == '\r') {
            continue;
        }
        if (isalpha(c)) {
            letters++;
        } else if (isdigit(c)) {
            digits++;
        } else if (isspace(c)) {
            spaces++;
        } else {
            others++;
        }
    }
    printf("%d %d %d %d\n", letters, digits, spaces, others);
    return 0;
}
